1	package org.springframework.samples.petclinic.util;
2	
3	import java.util.Map;
4	
5	/**
6	 * Pinned region-to-timezone reference table. Each canonical region (see {@link CityRegion}) maps to
7	 * its IANA timezone name; a region not in the table — including {@link CityRegion#UNKNOWN} — has no
8	 * timezone. Pure lookup with no dependency on other owners, so it is derived at response time rather
9	 * than stored on the entity.
10	 */
11	public final class RegionTimezone {
12	
13	    /** Region -> IANA timezone name. */
14	    private static final Map<String, String> REGION_TIMEZONES = Map.of(
15	            "NSW", "Australia/Sydney",
16	            "VIC", "Australia/Melbourne",
17	            "QLD", "Australia/Brisbane");
18	
19	    private RegionTimezone() {
20	    }
21	
22	    /**
23	     * The IANA timezone name for {@code region}, or {@code null} when the region is {@code null} or not
24	     * in the table.
25	     */
26	    public static String of(String region) {
27	        return region == null ? null : REGION_TIMEZONES.get(region);
28	    }
29	}
