1	package org.springframework.samples.petclinic.util;
2	
3	import java.time.LocalDate;
4	import java.util.Collection;
5	
6	/**
7	 * The owner's unified member id — the single identity that replaces the former customerCode and
8	 * membershipNumber. It is formatted {@code <REGION><FY><HASH8><CHK>}:
9	 * <ul>
10	 * <li>REGION — the region derived from the owner's postcode (falling back to the city; see
11	 * {@link Locality}),</li>
12	 * <li>FY — the two-digit {@link FiscalYear fiscal year} of the registration date,</li>
13	 * <li>HASH8 — the first eight upper-case hex characters of SHA-256 over the normalized telephone
14	 * concatenated with the last name (see {@link Sha256}), the same hash the region-and-hash identity
15	 * used,</li>
16	 * <li>CHK — a single {@link CheckDigit Luhn check digit} computed over the digits of
17	 * {@code <REGION><FY><HASH8>}.</li>
18	 * </ul>
19	 * The identity carries no per-owner sequence, so it does not depend on other owners; the same region,
20	 * fiscal year, telephone and last name always yield the same id. Every value that keys off the
21	 * owner's identity — the locality (and, through it, the timezone and owner segment), the create audit
22	 * record — therefore shares this single id. Pure functions, so exposed as plain helpers.
23	 */
24	public final class MemberId {
25	
26	    /** Number of hex characters in the hash portion of the id. */
27	    private static final int HASH_LENGTH = 8;
28	
29	    /** Number of digits in the fiscal-year portion of the id. */
30	    private static final int FY_LENGTH = 2;
31	
32	    /** Number of characters in the check-digit portion of the id. */
33	    private static final int CHECK_LENGTH = 1;
34	
35	    /** Length of the fixed FY + HASH8 + CHK tail that follows the variable-length region. */
36	    private static final int TAIL_LENGTH = FY_LENGTH + HASH_LENGTH + CHECK_LENGTH;
37	
38	    private MemberId() {
39	    }
40	
41	    /**
42	     * Builds the member id {@code <REGION><FY><HASH8><CHK>}. The hash is taken over the normalized
43	     * telephone followed by the last name; a {@code null} telephone or last name contributes an empty
44	     * string. The check digit is the Luhn digit over the digits of the {@code <REGION><FY><HASH8>}
45	     * body.
46	     */
47	    public static String of(String region, LocalDate registrationDate, String normalizedTelephone,
48	            String lastName) {
49	        String fy = String.format("%02d", FiscalYear.of(registrationDate) % 100);
50	        String hash8 = Sha256.prefix(orEmpty(normalizedTelephone) + orEmpty(lastName), HASH_LENGTH);
51	        String body = region + fy + hash8;
52	        return body + CheckDigit.of(body);
53	    }
54	
55	    /**
56	     * De-duplicates {@code candidate} against the {@code existing} member ids. Returns the candidate
57	     * unchanged when it does not collide; otherwise appends {@code -<n>} with the smallest {@code n} of
58	     * 2 or more that yields a value absent from {@code existing}.
59	     */
60	    public static String dedupe(String candidate, Collection<String> existing) {
61	        if (!existing.contains(candidate)) {
62	            return candidate;
63	        }
64	        for (int n = 2; ; n++) {
65	            String deduped = candidate + "-" + n;
66	            if (!existing.contains(deduped)) {
67	                return deduped;
68	            }
69	        }
70	    }
71	
72	    /** The REGION portion of a member id, or {@code null} when the id is absent. */
73	    public static String regionOf(String memberId) {
74	        if (memberId == null) {
75	            return null;
76	        }
77	        String base = base(memberId);
78	        return base.length() > TAIL_LENGTH ? base.substring(0, base.length() - TAIL_LENGTH) : base;
79	    }
80	
81	    /** The member id without any {@code -<n>} de-duplication suffix. */
82	    private static String base(String memberId) {
83	        int dash = memberId.indexOf('-');
84	        return dash < 0 ? memberId : memberId.substring(0, dash);
85	    }
86	
87	    private static String orEmpty(String value) {
88	        return value == null ? "" : value;
89	    }
90	}
