4	
5	/**
6	 * The owner's current primary identifier — the single value that identifies an owner across the
7	 * system. Now that the former customerCode and membershipNumber are unified, that is the
8	 * {@link MemberId memberId}. Callers that record "the primary identifier" (such as the owner-created
9	 * audit event) go through here, so the identity is sourced in one place rather than spread across
10	 * every consumer.
11	 */
12	public final class PrimaryIdentifier {
13	
14	    private PrimaryIdentifier() {
15	    }
16	
17	    /** The owner's current primary identifier, or {@code null} when the owner has none. */
18	    public static String of(Owner owner) {
19	        return owner.getMemberId();
20	    }
21	}
