1	package org.springframework.samples.petclinic.rest.function.owner;
2	
3	import net.officefloor.plugin.variable.Val;
4	import org.springframework.samples.petclinic.model.Owner;
5	import org.springframework.samples.petclinic.util.Locality;
6	import org.springframework.samples.petclinic.util.MemberId;
7	
8	/**
9	 * Assigns the owner's memberId, formatted {@code <REGION><FY><HASH8><CHK>} (see {@link MemberId}):
10	 * REGION is the region derived from the owner's postcode (falling back to the city; see
11	 * {@link Locality}), FY the two-digit fiscal year of the resolved registration date, HASH8 the first
12	 * eight upper-case hex characters of SHA-256 over the normalized telephone and last name, and CHK the
13	 * Luhn check digit over the {@code <REGION><FY><HASH8>} body. The owner's telephone is already in
14	 * canonical E.164 form here, having been normalized upstream by {@link NormalizeTelephone}, and its
15	 * registration date has been resolved by {@link ResolveRegistrationDate}. The identity carries no
16	 * per-owner sequence, so it does not depend on other owners. Mutates the built {@link Owner} in place.
17	 */
18	public class AssignMemberId {
19	
20	    public void service(@Val Owner owner) {
21	        String region = Locality.of(owner.getCity(), owner.getPostcode());
22	        owner.setMemberId(
23	                MemberId.of(region, owner.getRegistrationDate(), owner.getTelephone(), owner.getLastName()));
24	    }
25	}
