1	package org.springframework.samples.petclinic.rest.function.owner;
2	
3	import net.officefloor.plugin.variable.Val;
4	import org.springframework.samples.petclinic.model.Owner;
5	import org.springframework.samples.petclinic.repository.OwnerRepository;
6	import org.springframework.samples.petclinic.rest.dto.OwnerFieldsDto;
7	import org.springframework.samples.petclinic.rest.escalation.DuplicateIdentityException;
8	
9	/**
10	 * The duplicate block: a request is a hard duplicate when an existing active owner has the same
11	 * {@link IdentityKey identity key} (SHA-256 over the canonical telephone, email and {@link
12	 * org.springframework.samples.petclinic.util.Soundex Soundex} of the last name), and is rejected with
13	 * a 409 via {@link DuplicateIdentityException}. Because the telephone is part of the key, two owners
14	 * with the same last name and postcode but a <em>different</em> telephone are not a hard duplicate:
15	 * the request passes this block and is instead marked for follow-up by {@link FlagPossibleDuplicate}
16	 * and held to its household level ceiling by {@link CapMembershipLevel}. Setting {@code
17	 * sharesHousehold} bypasses this block outright, so the new owner is created as a declared household
18	 * member. The email-domain blocklist ({@link ValidateEmailDomain}) is applied earlier in the
19	 * pipeline, so a blocked address is already rejected before this step. Soft-deleted owners are
20	 * ignored, so a match that has since been deleted no longer blocks the create.
21	 */
22	public class EnsureUniqueIdentity {
23	
24	    public void service(@Val OwnerFieldsDto request, @Val Owner owner, OwnerRepository ownerRepository)
25	            throws DuplicateIdentityException {
26	        if (Boolean.TRUE.equals(request.getSharesHousehold())) {
27	            return;
28	        }
29	        String identityKey = IdentityKey.forOwner(owner);
30	        for (Owner existing : ownerRepository.findAll()) {
31	            if (existing.isActive() && identityKey.equals(IdentityKey.forOwner(existing))) {
32	                throw new DuplicateIdentityException(identityKey);
33	            }
34	        }
35	    }
36	}
37

1	package org.springframework.samples.petclinic.rest.function.owner;
2	
3	import java.util.Objects;
4	
5	import net.officefloor.plugin.variable.Val;
6	import org.springframework.samples.petclinic.model.Owner;
7	import org.springframework.samples.petclinic.repository.OwnerRepository;
8	import org.springframework.samples.petclinic.rest.dto.OwnerFieldsDto;
9	import org.springframework.samples.petclinic.util.Soundex;
10	
11	/**
12	 * Flags a soft duplicate: a new owner that passed the duplicate block (see
13	 * {@link EnsureUniqueIdentity}) with a <em>different</em> {@link IdentityKey identity key} from every
14	 * existing owner, yet still shares one's like-sounding last name ({@link Soundex}) and postcode. This
15	 * is the household-member case — same name and postcode but a different telephone, so a different
16	 * key. Such a request is allowed but marked for follow-up: the built {@link Owner} records
17	 * {@code possibleDuplicate} true and {@code possibleDuplicateOf} the matching owner's id (the earliest
18	 * match when several exist). A <em>declared</em> household member (the request set
19	 * {@code sharesHousehold}) is never flagged — deliberately sharing a household is not a suspected
20	 * duplicate. When nothing matches, {@code possibleDuplicate} is false and {@code possibleDuplicateOf}
21	 * stays absent. Runs before {@link SaveOwner}, so the new owner is not yet persisted and is never
22	 * matched against itself. Soft-deleted owners are ignored, mirroring the duplicate block in
23	 * {@link EnsureUniqueIdentity}. Mutates the built {@link Owner} in place.
24	 */
25	public class FlagPossibleDuplicate {
26	
27	    public void service(@Val OwnerFieldsDto request, @Val Owner owner, OwnerRepository ownerRepository) {
28	        owner.setPossibleDuplicate(false);
29	        if (Boolean.TRUE.equals(request.getSharesHousehold())) {
30	            return;
31	        }
32	        String identityKey = IdentityKey.forOwner(owner);
33	        String soundex = Soundex.of(owner.getLastName());
34	        String postcode = owner.getPostcode();
35	        Owner match = null;
36	        for (Owner existing : ownerRepository.findAll()) {
37	            if (existing.isActive()
38	                    && !identityKey.equals(IdentityKey.forOwner(existing))
39	                    && soundex.equals(Soundex.of(existing.getLastName()))
40	                    && Objects.equals(postcode, existing.getPostcode())) {
41	                if (match == null || existing.getId() < match.getId()) {
42	                    match = existing;
43	                }
44	            }
45	        }
46	        if (match != null) {
47	            owner.setPossibleDuplicate(true);
48	            owner.setPossibleDuplicateOf(match.getId());
49	        }
50	    }
51	}
