1	package org.springframework.samples.petclinic.rest.event;
2	
3	/**
4	 * Immutable structured record of an owner creation, emitted to the {@code AUDIT} log alongside the
5	 * human-readable audit line. Each event carries a process-wide monotonically increasing
6	 * {@code seq}, the owner's generated {@code ownerId}, its current primary identifier and the
7	 * membership level, under the {@code OWNER_CREATED} event type.
8	 *
9	 * <p>The {@code primaryIdentifier} is the value that identifies the owner — the unified
10	 * {@code memberId} — and is serialized under the {@code memberId} key.
11	 */
12	public record OwnerCreatedEvent(long seq, Integer ownerId, String primaryIdentifier, Integer membershipLevel) {
13	
14	    /** The event type discriminator carried in the serialized form. */
15	    public static final String EVENT = "OWNER_CREATED";
16	
17	    /** Renders the event as a compact JSON object with fields in the documented order. */
18	    public String toJson() {
19	        return "{"
20	                + "\"seq\":" + seq
21	                + ",\"ownerId\":" + ownerId
22	                + ",\"memberId\":" + jsonString(primaryIdentifier)
23	                + ",\"membershipLevel\":" + membershipLevel
24	                + ",\"event\":" + jsonString(EVENT)
25	                + "}";
26	    }
27	
28	    /** A JSON string literal for {@code value}, or the bare {@code null} literal when absent. */
29	    private static String jsonString(String value) {
30	        if (value == null) {
31	            return "null";
32	        }
33	        StringBuilder escaped = new StringBuilder("\"");
34	        for (int i = 0; i < value.length(); i++) {
35	            char c = value.charAt(i);
36	            if (c == '"' || c == '\\') {
37	                escaped.append('\\');
38	            }
39	            escaped.append(c);
40	        }
41	        return escaped.append('"').toString();
42	    }
43	}
