4	 * Bands {@link MembershipPoints membership points} into a membership level, a number from 1 to 4:
5	 * level 1 for 0-1 points, 2 for 2-3, 3 for 4-5 and 4 for 6 or more points. Because a newly created
6	 * owner has zero tenure, a new owner never earns the tenure points and so never exceeds level 3.
7	 */
8	public final class MembershipLevel {
9	
10	    private MembershipLevel() {
11	    }
12	
13	    /** The membership level for {@code points}, or {@code null} when {@code points} is {@code null}. */
14	    public static Integer forPoints(Integer points) {
15	        if (points == null) {
16	            return null;
17	        }
18	        if (points <= 1) {
19	            return 1;
20	        }
21	        if (points <= 3) {
22	            return 2;
23	        }
24	        if (points <= 5) {
25	            return 3;
26	        }
27	        return 4;
28	    }
29	}
