28	    public void service(@Val Owner owner) {
29	        Integer membershipLevel = MembershipLevel.forPoints(MembershipPoints.of(owner));
30	        OwnerCreatedEvent event = new OwnerCreatedEvent(SEQUENCE.incrementAndGet(),
31	                owner.getId(), PrimaryIdentifier.of(owner), membershipLevel);
32	        AUDIT.info("{}", event.toJson());
33	    }
